svg.script:
(function(){
  var root = document.querySelector('.a6p4-root');
  if(!root){
    var scripts = document.getElementsByTagName('script');
    var s = scripts[scripts.length-1];
    root = s && s.ownerSVGElement ? s.ownerSVGElement : null;
  }
  if(!root) return;

  function Q(sel){ return root.querySelector(sel); }
  var tip = Q('#a6p4-tip');
  var statusEl = Q('#a6p4-status');
  var liveEl = Q('#a6p4-live');
  var flipBtn = Q('#a6p4-btn-flip');
  var resetBtn = Q('#a6p4-btn-reset');
  var reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch(e){ reduce = false; }

  var timers = [];
  var playing = false;
  var eraOrder = ['acute','scar'];
  var eraIdx = 0;

  var labels = {
    acute: {
      tip1: 'Agudo · provocada',
      tip2: 'Inflamação/homeostase · não conta para epilepsia',
      stroke: 'var(--a6p4-coral, #F87171)',
      status: 'Era aguda · crise provocada',
      live: 'Na inflamação aguda a crise é provocada e não fecha critério de epilepsia.'
    },
    scar: {
      tip1: 'Sequela · foco',
      tip2: 'Cicatriz residual · pode abrir epilepsia depois',
      stroke: 'var(--a6p4-teal, #2DD4BF)',
      status: 'Era sequela · foco epileptogênico',
      live: 'A mesma meningite pode deixar foco; crises posteriores não provocadas mudam o jogo.'
    },
    meta: {
      tip1: 'Metabólico agudo',
      tip2: 'Na⁺ 140→105 ou hipoglicemia que cede ao repor',
      stroke: 'var(--a6p4-gold, #FBBF24)',
      status: 'Âncora de homeostase',
      live: 'Neurônio dispara por desarranjo agudo, sem cérebro epiléptico estrutural.'
    }
  };

  function clearTimers(){
    for(var i=0;i<timers.length;i++) clearTimeout(timers[i]);
    timers = [];
    playing = false;
    root.setAttribute('data-playing','0');
  }

  function setEra(era){
    if(!era){
      root.removeAttribute('data-era');
      if(statusEl){
        statusEl.textContent = 'Toque uma era · o relógio pinta a crise';
        statusEl.setAttribute('fill','var(--a6p4-muted, #94A3B8)');
      }
      if(liveEl) liveEl.textContent = 'Duas eras da mesma meningite. O tempo decide.';
      return;
    }
    root.setAttribute('data-era', era);
    var L = labels[era];
    if(statusEl && L){
      statusEl.textContent = L.status;
      statusEl.setAttribute('fill', L.stroke);
    }
    if(liveEl && L) liveEl.textContent = L.live;
    if(era === 'acute') eraIdx = 0;
    if(era === 'scar') eraIdx = 1;
  }

  function clientToSvg(cx, cy){
    var pt = root.createSVGPoint();
    pt.x = cx; pt.y = cy;
    var m = root.getScreenCTM();
    if(!m) return {x:cx, y:cy};
    var p = pt.matrixTransform(m.inverse());
    return {x:p.x, y:p.y};
  }

  function showTip(cx, cy, t1, t2, stroke){
    if(!tip) return;
    var t1el = Q('#a6p4-tip-t1');
    var t2el = Q('#a6p4-tip-t2');
    var bg = Q('#a6p4-tip-bg');
    if(t1el) t1el.textContent = t1;
    if(t2el) t2el.textContent = t2;
    if(bg) bg.setAttribute('stroke', stroke || 'var(--a6p4-gold, #FBBF24)');
    var p = clientToSvg(cx, cy);
    var w = 300, h = 58, off = 14;
    var x = p.x + off, y = p.y + off;
    if(x + w > 820) x = p.x - w - off;
    if(y + h > 620) y = p.y - h - off;
    if(x < 8) x = 8;
    if(y < 8) y = 8;
    tip.setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+')');
    tip.setAttribute('opacity','1');
    tip.setAttribute('aria-hidden','false');
  }

  function hideTip(){
    if(!tip) return;
    tip.setAttribute('opacity','0');
    tip.setAttribute('aria-hidden','true');
  }

  function flipSequence(){
    clearTimers();
    playing = true;
    root.setAttribute('data-playing','1');
    var seq = ['acute','scar','meta'];
    var i = 0;
    var stepOn = reduce ? 700 : 1000;
    var stepOff = reduce ? 200 : 280;
    function next(){
      if(i >= seq.length){
        timers.push(setTimeout(function(){
          setEra(null);
          playing = false;
          root.setAttribute('data-playing','0');
          if(statusEl){
            statusEl.textContent = 'Ciclo completo · o tempo decide a cor da crise';
            statusEl.setAttribute('fill','var(--a6p4-gold, #FBBF24)');
          }
          if(liveEl) liveEl.textContent = 'Agudo provocada × sequela com foco. Metabólico ancora a homeostase.';
        }, stepOff));
        return;
      }
      var e = seq[i];
      setEra(e);
      i++;
      timers.push(setTimeout(function(){
        timers.push(setTimeout(next, stepOff));
      }, stepOn));
    }
    next();
  }

  function bindEra(el){
    if(!el) return;
    var era = el.getAttribute('data-era');
    var L = labels[era];
    function activate(ev){
      clearTimers();
      setEra(era);
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 80;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 40;
      if(L) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
    }
    el.addEventListener('mouseenter', function(ev){
      if(playing) return;
      setEra(era);
      if(L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mousemove', function(ev){
      if(playing) return;
      if(tip && tip.getAttribute('opacity')==='1' && L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mouseleave', function(){
      if(playing) return;
      hideTip();
    });
    el.addEventListener('click', activate);
    el.addEventListener('focus', function(){
      if(playing) return;
      setEra(era);
      var b = el.getBoundingClientRect();
      if(L) showTip(b.left + b.width/2, b.top + b.height/2, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('blur', function(){ if(!playing) hideTip(); });
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        activate(ev);
      }
    });
  }

  bindEra(Q('#a6p4-era-acute'));
  bindEra(Q('#a6p4-era-scar'));

  var pivot = Q('#a6p4-pivot');
  if(pivot){
    function pivotAct(ev){
      clearTimers();
      eraIdx = (eraIdx + 1) % 2;
      var era = eraOrder[eraIdx];
      setEra(era);
      var L = labels[era];
      var b = pivot.getBoundingClientRect();
      var cx = (ev && ev.clientX != null) ? ev.clientX : b.left + b.width/2;
      var cy = (ev && ev.clientY != null) ? ev.clientY : b.top + b.height/2;
      if(L) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
    }
    pivot.addEventListener('click', pivotAct);
    pivot.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); pivotAct(ev); }
    });
  }

  if(flipBtn){
    flipBtn.addEventListener('click', flipSequence);
    flipBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); flipSequence(); }
    });
  }
  if(resetBtn){
    resetBtn.addEventListener('click', function(){ clearTimers(); setEra(null); hideTip(); });
    resetBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); clearTimers(); setEra(null); hideTip(); }
    });
  }

  var chips = {
    time: ['Tempo + contexto', 'Não leia só a palavra meningite: leia quando e por quê.', 'var(--a6p4-gold, #FBBF24)'],
    label: ['Rótulo não basta', 'Sempre epiléptico ou nunca epiléptico: ambos erram sem o relógio.', 'var(--a6p4-indigo, #818CF8)'],
    na: ['Na⁺ 140 → 105', 'Queda rápida: crise provocada sem foco epiléptico estrutural.', 'var(--a6p4-coral, #F87171)'],
    glu: ['Hipoglicemia', 'Repor glicose → crise cede: âncora metabólica aguda.', 'var(--a6p4-gold, #FBBF24)'],
    inflam: ['Inflamação meníngea', 'Na fase aguda, inflamação provoca a crise — não conta para epilepsia.', 'var(--a6p4-coral, #F87171)'],
    focus: ['Foco residual', 'Cicatriz da mesma doença: porta para crises não provocadas depois.', 'var(--a6p4-teal, #2DD4BF)']
  };

  function bindChip(id, key, forceMeta){
    var el = Q(id);
    if(!el) return;
    var data = chips[key];
    function go(ev){
      var cx = (ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 14;
      showTip(cx, cy, data[0], data[1], data[2]);
      if(forceMeta){
        setEra('meta');
      } else if(key === 'inflam' || key === 'na' || key === 'glu'){
        setEra(key === 'focus' ? 'scar' : (key === 'inflam' || key === 'na' || key === 'glu' ? (key === 'focus' ? 'scar' : (key === 'inflam' ? 'acute' : 'meta')) : null));
        if(key === 'inflam') setEra('acute');
        else if(key === 'focus') setEra('scar');
        else setEra('meta');
      } else if(key === 'focus'){
        setEra('scar');
      }
      if(liveEl) liveEl.textContent = data[0] + '. ' + data[1];
      if(statusEl){
        statusEl.textContent = data[0];
        statusEl.setAttribute('fill', data[2]);
      }
    }
    el.addEventListener('mouseenter', go);
    el.addEventListener('mousemove', function(ev){ if(tip && tip.getAttribute('opacity')==='1') go(ev); });
    el.addEventListener('mouseleave', hideTip);
    el.addEventListener('focus', function(){
      var b = el.getBoundingClientRect();
      showTip(b.left + b.width/2, b.top + b.height/2, data[0], data[1], data[2]);
    });
    el.addEventListener('blur', hideTip);
    el.addEventListener('click', go);
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); go(ev); }
    });
  }
  bindChip('#a6p4-chip-time','time', false);
  bindChip('#a6p4-chip-label','label', false);
  bindChip('#a6p4-chip-na','na', true);
  bindChip('#a6p4-chip-glu','glu', true);
  bindChip('#a6p4-chip-inflam','inflam', false);
  bindChip('#a6p4-chip-focus','focus', false);

  root.addEventListener('click', function(ev){
    var t = ev.target;
    var eras = Q('#a6p4-eras');
    var meta = Q('#a6p4-meta');
    var chipsG = Q('#a6p4-chips');
    var ctrls = Q('#a6p4-controls');
    var pivotG = Q('#a6p4-pivot');
    if(eras && eras.contains(t)) return;
    if(meta && meta.contains(t)) return;
    if(chipsG && chipsG.contains(t)) return;
    if(ctrls && ctrls.contains(t)) return;
    if(pivotG && pivotG.contains(t)) return;
    hideTip();
  });

  setEra(null);
})();
